redis.time_control:
// miniredis 支持手动推进时间，验证 TTL 过期
mr.FastForward(10 * time.Minute)
// 此时所有 TTL < 10min 的 key 已过期

computed_getters.body:
if (type == 'video' || (videoUrl != null && videoUrl!.isNotEmpty)) return 'video';
if (type == 'article') return 'note';
if (type == 'image') return 'image';
if (imageUrls.isNotEmpty) return 'image';
return 'note';

if (videoUrl != null && videoUrl!.isNotEmpty) return 'video';
if (imageUrls.isNotEmpty) return 'image';
return 'note';

if (workType == 'video' || (videoUrl != null && videoUrl!.isNotEmpty)) return 'video';
if (workType == 'article' || workType == 'note') return 'article';
if (workType == 'micro' || workType == 'moment') return 'micro';
return 'image';

final fromContract = mediaItems
    .where((item) => item.kind == 'video' && item.url.isNotEmpty)
    .toList(growable: false);
if (fromContract.isNotEmpty) return fromContract;
final fallback = videoUrl;
if (fallback == null || fallback.isEmpty) return const <WorkBrowserMediaItemDto>[];
return <WorkBrowserMediaItemDto>[
  WorkBrowserMediaItemDto(
    kind: 'video',
    url: fallback,
    coverUrl: thumbnailUrl.isNotEmpty
        ? thumbnailUrl
        : (coverUrl.isEmpty ? null : coverUrl),
    durationMs: durationMs,
    mediaAssetId: mediaAssetId,
    mediaAssetVersion: mediaAssetVersion,
    previewTrackManifestUrl: previewTrackManifestUrl,
    previewTrackVersion: previewTrackVersion,
    width: width,
    height: height,
    title: null,
  ),
];

final fromContract = mediaItems
    .where((item) => item.kind == 'image' && item.url.isNotEmpty)
    .map((item) => item.url)
    .toList(growable: false);
if (fromContract.isNotEmpty) return fromContract;
return imageUrls;
